import rigData from './rigs.json';

/** How a drawn character's parts fit together. Generated by `npm run art`. */
export interface RigSlot {
  image: string; // texture key
  pos: [number, number]; // joint position in game pixels
  origin: [number, number]; // pivot inside the image (0..1)
}

export interface Rig {
  displayScale: number;
  hip: [number, number];
  images: { key: string; file: string }[];
  slots: Record<'legB' | 'legF' | 'torso' | 'head' | 'armB' | 'armF', RigSlot>;
}

export const RIGS = rigData as unknown as Record<string, Rig>;
